64	
65	std::unique_ptr<BtHandshakeMessage>
66	DefaultBtMessageReceiver::receiveHandshake(bool quickReply)
67	{
68	  A2_LOG_DEBUG(
69	      fmt("Receiving handshake bufferLength=%lu",
70	          static_cast<unsigned long>(peerConnection_->getBufferLength())));
71	  unsigned char data[BtHandshakeMessage::MESSAGE_LENGTH];
72	  size_t dataLength = BtHandshakeMessage::MESSAGE_LENGTH;
73	  if (handshakeSent_ || !quickReply ||
74	      peerConnection_->getBufferLength() < 48) {
75	    if (peerConnection_->receiveHandshake(data, dataLength)) {
76	      auto msg = messageFactory_->createHandshakeMessage(data, dataLength);
77	      msg->validate();
78	      return msg;
79	    }
80	  }
81	  else {
82	    // Handle tracker's NAT-checking feature
83	    handshakeSent_ = true;
84	    // check info_hash
85	    if (memcmp(bittorrent::getInfoHash(downloadContext_),
86	               peerConnection_->getBuffer() + 28, INFO_HASH_LENGTH) == 0) {
87	      sendHandshake();
88	    }
89	    else {
90	      throw DL_ABORT_EX(
91	          fmt("Bad Info Hash %s",
92	              util::toHex(peerConnection_->getBuffer() + 28, INFO_HASH_LENGTH)
93	                  .c_str()));
94	    }
95	    if (peerConnection_->getBufferLength() ==
96	            BtHandshakeMessage::MESSAGE_LENGTH &&
97	        peerConnection_->receiveHandshake(data, dataLength)) {
98	      auto msg = messageFactory_->createHandshakeMessage(data, dataLength);
99	      msg->validate();
100	      return msg;
101	    }
102	  }
103	  return nullptr;
104	}
105	
106	std::unique_ptr<BtHandshakeMessage>
107	DefaultBtMessageReceiver::receiveAndSendHandshake()
108	{
109	  return receiveHandshake(true);
110	}
