112	void DefaultBtMessageReceiver::sendHandshake()
113	{
114	  dispatcher_->addMessageToQueue(messageFactory_->createHandshakeMessage(
115	      bittorrent::getInfoHash(downloadContext_),
116	      bittorrent::getStaticPeerId()));
117	  dispatcher_->sendMessages();
118	}
119	
120	std::unique_ptr<BtMessage> DefaultBtMessageReceiver::receiveMessage()
121	{
122	  size_t dataLength = 0;
123	  // Give 0 to PeerConnection::receiveMessage() to prevent memcpy.
124	  if (!peerConnection_->receiveMessage(nullptr, dataLength)) {
125	    return nullptr;
126	  }
127	  auto msg = messageFactory_->createBtMessage(
128	      peerConnection_->getMsgPayloadBuffer(), dataLength);
129	  msg->validate();
130	  if (msg->getId() == BtPieceMessage::ID) {
131	    auto piecemsg = static_cast<BtPieceMessage*>(msg.get());
132	    piecemsg->setMsgPayload(peerConnection_->getMsgPayloadBuffer());
133	  }
134	  return msg;
135	}
