86	void DefaultBtMessageDispatcher::sendMessagesInternal()
87	{
88	  auto tempQueue = std::vector<std::unique_ptr<BtMessage>>{};
89	  while (!messageQueue_.empty()) {
90	    auto msg = std::move(messageQueue_.front());
91	    messageQueue_.pop_front();
92	    if (msg->isUploading()) {
93	      if (requestGroupMan_->doesOverallUploadSpeedExceed() ||
94	          downloadContext_->getOwnerRequestGroup()->doesUploadSpeedExceed()) {
95	        tempQueue.push_back(std::move(msg));
96	        continue;
97	      }
98	    }
99	    msg->send();
100	  }
101	  if (!tempQueue.empty()) {
102	    messageQueue_.insert(std::begin(messageQueue_),
103	                         std::make_move_iterator(std::begin(tempQueue)),
104	                         std::make_move_iterator(std::end(tempQueue)));
105	  }
106	}
107	
108	void DefaultBtMessageDispatcher::sendMessages()
109	{
110	  if (peerConnection_->getBufferEntrySize() < A2_IOV_MAX) {
111	    sendMessagesInternal();
112	  }
113	  peerConnection_->sendPendingData();
114	}
