118	toRawPointers(const std::deque<std::unique_ptr<BtMessage>>& v)
119	{
120	  auto x = std::vector<BtMessage*>{};
121	  x.reserve(v.size());
122	  for (auto& i : v) {
123	    x.push_back(i.get());
124	  }
