148	namespace {
149	void abortOutstandingRequest(const RequestSlot* slot,
150	                             const std::shared_ptr<Piece>& piece, cuid_t cuid)
151	{
152	  A2_LOG_DEBUG(fmt(MSG_DELETING_REQUEST_SLOT, cuid,
153	                   static_cast<unsigned long>(slot->getIndex()),
154	                   slot->getBegin(),
155	                   static_cast<unsigned long>(slot->getBlockIndex())));
156	  piece->cancelBlock(slot->getBlockIndex());
157	}
