159	
160	// localhost cancels outstanding download requests to the peer.
161	void DefaultBtMessageDispatcher::doAbortOutstandingRequestAction(
162	    const std::shared_ptr<Piece>& piece)
163	{
164	  for (auto& slot : requestSlots_) {
165	    if (slot->getIndex() == piece->getIndex()) {
166	      abortOutstandingRequest(slot.get(), piece, cuid_);
167	    }
168	  }
169	  requestSlots_.erase(
170	      std::remove_if(std::begin(requestSlots_), std::end(requestSlots_),
171	                     [&](const std::unique_ptr<RequestSlot>& slot) {
172	                       return slot->getIndex() == piece->getIndex();
173	                     }),
174	      std::end(requestSlots_));
175	
176	  BtAbortOutstandingRequestEvent event(piece);
177	
178	  auto tempQueue = toRawPointers(messageQueue_);
179	  for (auto i : tempQueue) {
180	    i->onAbortOutstandingRequestEvent(event);
181	  }
182	}
183	
184	// localhost received choke message from the peer.
185	void DefaultBtMessageDispatcher::doChokedAction()
186	{
187	  for (auto& slot : requestSlots_) {
188	    if (!peer_->isInPeerAllowedIndexSet(slot->getIndex())) {
189	      A2_LOG_DEBUG(fmt(MSG_DELETING_REQUEST_SLOT_CHOKED, cuid_,
190	                       static_cast<unsigned long>(slot->getIndex()),
191	                       slot->getBegin(),
192	                       static_cast<unsigned long>(slot->getBlockIndex())));
193	      slot->getPiece()->cancelBlock(slot->getBlockIndex());
194	    }
195	  }
196	  requestSlots_.erase(
197	      std::remove_if(std::begin(requestSlots_), std::end(requestSlots_),
198	                     [&](const std::unique_ptr<RequestSlot>& slot) {
199	                       return !peer_->isInPeerAllowedIndexSet(slot->getIndex());
200	                     }),
201	      std::end(requestSlots_));
202	}
203	
204	// localhost dispatched choke message to the peer.
205	void DefaultBtMessageDispatcher::doChokingAction()
206	{
207	  BtChokingEvent event;
208	
209	  auto tempQueue = toRawPointers(messageQueue_);
210	  for (auto i : tempQueue) {
211	    i->onChokingEvent(event);
212	  }
213	}
214	
215	void DefaultBtMessageDispatcher::checkRequestSlotAndDoNecessaryThing()
216	{
217	  for (auto& slot : requestSlots_) {
218	    if (slot->isTimeout(requestTimeout_)) {
219	      A2_LOG_DEBUG(fmt(MSG_DELETING_REQUEST_SLOT_TIMEOUT, cuid_,
220	                       static_cast<unsigned long>(slot->getIndex()),
221	                       slot->getBegin(),
222	                       static_cast<unsigned long>(slot->getBlockIndex())));
223	      slot->getPiece()->cancelBlock(slot->getBlockIndex());
224	      peer_->snubbing(true);
225	    }
226	    else if (slot->getPiece()->hasBlock(slot->getBlockIndex())) {
227	      A2_LOG_DEBUG(fmt(MSG_DELETING_REQUEST_SLOT_ACQUIRED, cuid_,
228	                       static_cast<unsigned long>(slot->getIndex()),
229	                       slot->getBegin(),
230	                       static_cast<unsigned long>(slot->getBlockIndex())));
231	      addMessageToQueue(messageFactory_->createCancelMessage(
232	          slot->getIndex(), slot->getBegin(), slot->getLength()));
233	    }
234	  }
235	  requestSlots_.erase(
236	      std::remove_if(std::begin(requestSlots_), std::end(requestSlots_),
237	                     [&](const std::unique_ptr<RequestSlot>& slot) {
238	                       return slot->isTimeout(requestTimeout_) ||
239	                              slot->getPiece()->hasBlock(slot->getBlockIndex());
240	                     }),
241	      std::end(requestSlots_));
242	}
