250	                                                      size_t blockIndex)
251	{
252	  for (auto& slot : requestSlots_) {
253	    if (slot->getIndex() == index && slot->getBlockIndex() == blockIndex) {
254	      return true;
255	    }
256	  }
257	  return false;
258	}
