244	bool DefaultBtMessageDispatcher::isSendingInProgress()
245	{
246	  return peerConnection_->getBufferEntrySize();
247	}
248	
249	bool DefaultBtMessageDispatcher::isOutstandingRequest(size_t index,
250	                                                      size_t blockIndex)
251	{
252	  for (auto& slot : requestSlots_) {
253	    if (slot->getIndex() == index && slot->getBlockIndex() == blockIndex) {
254	      return true;
255	    }
256	  }
257	  return false;
258	}
259	
260	const RequestSlot*
261	DefaultBtMessageDispatcher::getOutstandingRequest(size_t index, int32_t begin,
262	                                                  int32_t length)
263	{
264	  for (auto& slot : requestSlots_) {
265	    if (slot->getIndex() == index && slot->getBegin() == begin &&
266	        slot->getLength() == length) {
267	      return slot.get();
268	    }
269	  }
270	  return nullptr;
271	}
272	
273	void DefaultBtMessageDispatcher::removeOutstandingRequest(
274	    const RequestSlot* slot)
275	{
276	  for (auto i = std::begin(requestSlots_), eoi = std::end(requestSlots_);
277	       i != eoi; ++i) {
278	    if (*(*i) == *slot) {
279	      abortOutstandingRequest((*i).get(), (*i)->getPiece(), cuid_);
280	      requestSlots_.erase(i);
281	      break;
282	    }
283	  }
284	}
285	
286	void DefaultBtMessageDispatcher::addOutstandingRequest(
287	    std::unique_ptr<RequestSlot> slot)
288	{
289	  requestSlots_.push_back(std::move(slot));
290	}
