91	std::unique_ptr<BtMessage>
92	DefaultBtMessageFactory::createBtMessage(const unsigned char* data,
93	                                         size_t dataLength)
94	{
95	  auto msg = std::unique_ptr<AbstractBtMessage>{};
96	  if (dataLength == 0) {
97	    // keep-alive
98	    msg = make_unique<BtKeepAliveMessage>();
99	  }
100	  else {
101	    uint8_t id = bittorrent::getId(data);
102	    switch (id) {
103	    case BtChokeMessage::ID:
104	      msg = BtChokeMessage::create(data, dataLength);
105	      break;
106	    case BtUnchokeMessage::ID:
107	      msg = BtUnchokeMessage::create(data, dataLength);
108	      break;
109	    case BtInterestedMessage::ID: {
110	      auto m = BtInterestedMessage::create(data, dataLength);
111	      m->setPeerStorage(peerStorage_);
112	      msg = std::move(m);
113	      break;
114	    }
115	    case BtNotInterestedMessage::ID: {
116	      auto m = BtNotInterestedMessage::create(data, dataLength);
117	      m->setPeerStorage(peerStorage_);
118	      msg = std::move(m);
119	      break;
120	    }
121	    case BtHaveMessage::ID:
122	      msg = BtHaveMessage::create(data, dataLength);
123	      if (!metadataGetMode_) {
124	        msg->setBtMessageValidator(make_unique<IndexBtMessageValidator>(
125	            static_cast<BtHaveMessage*>(msg.get()),
126	            downloadContext_->getNumPieces()));
127	      }
128	      break;
129	    case BtBitfieldMessage::ID:
130	      msg = BtBitfieldMessage::create(data, dataLength);
131	      if (!metadataGetMode_) {
132	        msg->setBtMessageValidator(make_unique<BtBitfieldMessageValidator>(
133	            static_cast<BtBitfieldMessage*>(msg.get()),
134	            downloadContext_->getNumPieces()));
135	      }
136	      break;
137	    case BtRequestMessage::ID: {
138	      auto m = BtRequestMessage::create(data, dataLength);
139	      if (!metadataGetMode_) {
140	        m->setBtMessageValidator(make_unique<RangeBtMessageValidator>(
141	            static_cast<BtRequestMessage*>(m.get()),
142	            downloadContext_->getNumPieces(),
143	            pieceStorage_->getPieceLength(m->getIndex())));
144	      }
145	      msg = std::move(m);
146	      break;
147	    }
148	    case BtPieceMessage::ID: {
149	      auto m = BtPieceMessage::create(data, dataLength);
150	      if (!metadataGetMode_) {
151	        m->setBtMessageValidator(make_unique<BtPieceMessageValidator>(
152	            static_cast<BtPieceMessage*>(m.get()),
153	            downloadContext_->getNumPieces(),
154	            pieceStorage_->getPieceLength(m->getIndex())));
155	      }
156	      m->setDownloadContext(downloadContext_);
157	      m->setPeerStorage(peerStorage_);
158	      msg = std::move(m);
159	      break;
160	    }
161	    case BtCancelMessage::ID: {
162	      auto m = BtCancelMessage::create(data, dataLength);
163	      if (!metadataGetMode_) {
164	        m->setBtMessageValidator(make_unique<RangeBtMessageValidator>(
165	            static_cast<BtCancelMessage*>(m.get()),
166	            downloadContext_->getNumPieces(),
167	            pieceStorage_->getPieceLength(m->getIndex())));
168	      }
169	      msg = std::move(m);
170	      break;
171	    }
172	    case BtPortMessage::ID: {
173	      auto m = BtPortMessage::create(data, dataLength);
174	      m->setLocalNode(localNode_);
175	      m->setRoutingTable(routingTable_);
176	      m->setTaskQueue(taskQueue_);
177	      m->setTaskFactory(taskFactory_);
178	      msg = std::move(m);
179	      break;
180	    }
181	    case BtSuggestPieceMessage::ID: {
182	      auto m = BtSuggestPieceMessage::create(data, dataLength);
183	      if (!metadataGetMode_) {
184	        m->setBtMessageValidator(make_unique<IndexBtMessageValidator>(
185	            static_cast<BtSuggestPieceMessage*>(m.get()),
186	            downloadContext_->getNumPieces()));
187	      }
188	      msg = std::move(m);
189	      break;
190	    }
191	    case BtHaveAllMessage::ID:
192	      msg = BtHaveAllMessage::create(data, dataLength);
193	      break;
194	    case BtHaveNoneMessage::ID:
195	      msg = BtHaveNoneMessage::create(data, dataLength);
196	      break;
197	    case BtRejectMessage::ID: {
198	      auto m = BtRejectMessage::create(data, dataLength);
199	      if (!metadataGetMode_) {
200	        m->setBtMessageValidator(make_unique<RangeBtMessageValidator>(
201	            static_cast<BtRejectMessage*>(m.get()),
202	            downloadContext_->getNumPieces(),
203	            pieceStorage_->getPieceLength(m->getIndex())));
204	      }
205	      msg = std::move(m);
206	      break;
207	    }
208	    case BtAllowedFastMessage::ID: {
209	      auto m = BtAllowedFastMessage::create(data, dataLength);
210	      if (!metadataGetMode_) {
211	        m->setBtMessageValidator(make_unique<IndexBtMessageValidator>(
212	            static_cast<BtAllowedFastMessage*>(m.get()),
213	            downloadContext_->getNumPieces()));
214	      }
215	      msg = std::move(m);
216	      break;
217	    }
218	    case BtExtendedMessage::ID: {
219	      if (peer_->isExtendedMessagingEnabled()) {
220	        msg = BtExtendedMessage::create(extensionMessageFactory_, peer_, data,
221	                                        dataLength);
222	      }
223	      else {
224	        throw DL_ABORT_EX("Received extended message from peer during"
225	                          " a session with extended messaging disabled.");
226	      }
227	      break;
228	    }
229	    default:
230	      throw DL_ABORT_EX(fmt("Invalid message ID. id=%u", id));
231	    }
232	  }
233	  setCommonProperty(msg.get());
234	  return std::move(msg);
235	}
